    '        }\n' +
    '    }\n' +
    '}\n';
}
const tests = {
  database: dslFor('a = database "DB" "d"'),
  queue: dslFor('a = queue "Q" "d"'),
  cache: dslFor('a = cache "C" "d"'),
  documentStore: dslFor('a = documentStore "DS" "d"'),
  container: dslFor('a = container "C" "d" "t"'),
};
const out = {};
for (const [k, dsl] of Object.entries(tests)) {
  const r = await tools.structurizr.validate({ dsl });
  out[k] = r;
}
return out;

